mapper.select:
select b.name as brandName,c1.name as category1Name,c2.name as category2Name,c3.name as category3Name,p.*
from product p
inner join brand b on p.brand_id = b.id
inner join category c1 on c1.id = p.category1_id
inner join category c2 on c2.id = p.category2_id
inner join category c3 on c3.id = p.category3_id


        and p.brand_id = #{productDto.brandId}


        and p.category1_id = #{productDto.category1Id}


        and p.category2_id = #{productDto.category2Id}


        and p.category3_id = #{productDto.category3Id}

    and p.is_deleted = 0 and b.is_deleted = 0 and c1.is_deleted = 0

order by p.id asc
